//! Prints a regenerated `src/commonstring.rs` (from the embedded TPK common string table)
//! to stdout. Run via `just update-commonstring`.

use rabex::tpk::TpkTypeTreeBlob;
use std::collections::BTreeMap;

const HEADER: &str = r#"
//! @generated by `just update-commonstring` from the embedded TPK — do not edit by hand.

use std::collections::BTreeMap;
use std::sync::LazyLock;

pub static COMMONSTRING: LazyLock<BTreeMap<u32, &'static str>> = LazyLock::new(|| {
    [
"#;

const FOOTER: &str = r#"    ]
    .iter()
    .copied()
    .collect()
});
"#;

fn main() {
    let tpk = TpkTypeTreeBlob::embedded();
    let mut strings = BTreeMap::new();
    for (version, entries) in &tpk.common_string.version_information {
        for entry in entries {
            let s = tpk.string_buffer[entry.string as usize].as_str();
            if let Some(prev) = strings.insert(entry.offset, s) {
                assert_eq!(prev, s, "offset {} in {version}", entry.offset);
            }
        }
    }

    print!("{HEADER}");
    for (offset, s) in &strings {
        println!("        ({offset}, {s:?}),");
    }
    print!("{FOOTER}");
}
